import { ColorScheme } from '@/contexts/ThemeContext';
import { Equipment, MaintenanceLog, FuelLog, Consumable, FuelType, BUILT_IN_FUEL_TYPES } from '@/types/equipment';

const LOGO_BASE64 = '';

const LIGHT_PRIMARY_IDS = new Set(['caterpillar', 'versatile']);

export function getContrastTextColor(hex: string): string {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.5 ? '#1A1A1A' : '#FFFFFF';
}

export function getPdfPrimaryColor(scheme: ColorScheme): string {
  if (LIGHT_PRIMARY_IDS.has(scheme.id)) {
    return scheme.primaryDark;
  }
  const r = parseInt(scheme.primary.slice(1, 3), 16);
  const g = parseInt(scheme.primary.slice(3, 5), 16);
  const b = parseInt(scheme.primary.slice(5, 7), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.6 ? scheme.primaryDark : scheme.primary;
}

function getFuelTypeLabel(fuelType: FuelType, customName?: string): string {
  if (fuelType === 'custom' && customName) return customName;
  const found = BUILT_IN_FUEL_TYPES.find(ft => ft.value === fuelType);
  return found ? found.label : fuelType;
}

function getMetricLabel(equipment: Equipment): string {
  return equipment.metric === 'miles' ? 'Miles' : 'Hours';
}

export interface MaintenancePdfOptions {
  equipment: Equipment[];
  maintenanceLogs: MaintenanceLog[];
  fuelLogs: FuelLog[];
  consumables: Consumable[];
  colorScheme: ColorScheme;
  dateRange: { start: string; end: string; label: string };
  includeFuel: boolean;
  includeNotes: boolean;
  includeAttachments: boolean;
  isBatchSummary: boolean;
  generationDate: string;
}

export interface FuelPdfOptions {
  equipment: Equipment[];
  fuelLogs: FuelLog[];
  colorScheme: ColorScheme;
  dateRange: { start: string; end: string; label: string };
  generationDate: string;
}

