function renderHeader(
  logoSrc: string,
  primaryColor: string,
  contrastText: string,
  subtitle: string,
  generationDate: string,
  dateRangeLabel: string,
): string {
  return `
    <div class="page-header">
      <div class="page-header-left">
        <img src="${logoSrc}" alt="FarmGuard Logo" />
        <div>
          <h1>FarmGuard Maintenance</h1>
          <div class="subtitle">${subtitle}</div>
        </div>
      </div>
      <div class="page-header-right">
        <div>Generated: ${generationDate}</div>
        <div>Date Range: ${dateRangeLabel}</div>
      </div>
    </div>`;
}

function renderEquipmentHeader(eq: Equipment, primaryColor: string, contrastText: string): string {
  const metricLabel = getMetricLabel(eq);
  return `
    <div class="equipment-header">
      <h2>${eq.name}</h2>
    </div>
    <div class="equipment-details">
      <div class="detail-item"><div class="detail-label">Make</div><div class="detail-value">${eq.make}</div></div>
      <div class="detail-item"><div class="detail-label">Model</div><div class="detail-value">${eq.model}</div></div>
      <div class="detail-item"><div class="detail-label">Year</div><div class="detail-value">${eq.year}</div></div>
      <div class="detail-item"><div class="detail-label">Serial Number</div><div class="detail-value">${eq.serialNumber || 'N/A'}</div></div>
      <div class="detail-item"><div class="detail-label">Current ${metricLabel}</div><div class="detail-value">${eq.currentHours.toLocaleString()}</div></div>
      ${eq.oilCapacity ? `<div class="detail-item"><div class="detail-label">Oil Capacity</div><div class="detail-value">${eq.oilCapacity}</div></div>` : ''}
    </div>`;
}

function renderFooter(generationDate: string): string {
  return `
    <div class="page-footer">
      <span>FarmGuard Maintenance</span>
      <span>${generationDate}</span>
      <span>End of Report</span>
    </div>`;
}

export function generateMaintenancePdfHtml(options: MaintenancePdfOptions): string {
  const {
    equipment,
    maintenanceLogs,
    fuelLogs,
    consumables,
    colorScheme,
    dateRange,
    includeFuel,
    includeNotes,
    includeAttachments,
    isBatchSummary,
    generationDate,
  } = options;

  const primaryColor = getPdfPrimaryColor(colorScheme);
  const contrastText = getContrastTextColor(primaryColor);
  const logoSrc = `data:image/jpeg;base64,${LOGO_BASE64}`;

  let html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Equipment Service Report</title>${getBaseStyles(primaryColor, contrastText)}</head><body>`;

  html += renderHeader(logoSrc, primaryColor, contrastText, 'Equipment Service Report', generationDate, dateRange.label);

  if (isBatchSummary && equipment.length > 1) {
    html += `<div class="section-title">Equipment Summary</div>`;
    html += `<table class="summary-table"><thead><tr>
      <th>Equipment</th>
      <th>Make / Model</th>
      <th>Current Hours</th>
      <th>Maintenance Records</th>
      <th>Fuel Fill-Ups</th>
    </tr></thead><tbody>`;

    for (const eq of equipment) {
      const mCount = maintenanceLogs.filter(l => l.equipmentId === eq.id).length;
      const fCount = fuelLogs.filter(l => l.equipmentId === eq.id).length;
      const metricLabel = getMetricLabel(eq);
      html += `<tr>
        <td><strong>${eq.name}</strong></td>
        <td>${eq.make} ${eq.model}</td>
        <td>${eq.currentHours.toLocaleString()} ${metricLabel.toLowerCase()}</td>
        <td>${mCount}</td>
        <td>${fCount}</td>
      </tr>`;
    }

    html += `</tbody></table>`;
  }

  for (let i = 0; i < equipment.length; i++) {
    const eq = equipment[i];
    const eqMaintLogs = maintenanceLogs.filter(l => l.equipmentId === eq.id);
    const eqFuelLogs = fuelLogs.filter(l => l.equipmentId === eq.id);
    const metricLabel = getMetricLabel(eq);

    html += `<div class="${i > 0 ? 'equipment-section' : ''}">`;
    html += renderEquipmentHeader(eq, primaryColor, contrastText);

    html += `<div class="section-title">Maintenance Records</div>`;
    if (eqMaintLogs.length === 0) {
      html += `<div class="no-records">No maintenance records found for this date range.</div>`;
    } else {
      for (const log of eqMaintLogs) {
        const typeClass = `type-${log.type}`;
        const typeLabel = log.type.charAt(0).toUpperCase() + log.type.slice(1);

        html += `<div class="maintenance-card">`;
        html += `<div class="maintenance-card-header">
          <span class="date">${log.date}</span>
          <span class="type-badge ${typeClass}">${typeLabel}</span>
        </div>`;
        html += `<div class="maintenance-card-body">`;
        html += `<p><span class="label">Description:</span> ${log.description}</p>`;
        html += `<p><span class="label">${metricLabel} at Service:</span> ${log.hoursAtService.toLocaleString()}</p>`;

        if (log.performedByName) {
          html += `<p><span class="label">Performed By:</span> ${log.performedByName} (${log.performedBy})</p>`;
        } else {
          html += `<p><span class="label">Performed By:</span> ${log.performedBy.charAt(0).toUpperCase() + log.performedBy.slice(1)}</p>`;
        }

        if (log.downtimeHours !== undefined && log.downtimeHours > 0) {
          html += `<p><span class="label">Downtime:</span> ${log.downtimeHours} hours</p>`;
        }

        if (log.consumablesUsed && log.consumablesUsed.length > 0) {
          html += `<p><span class="label">Parts Used:</span></p><div class="parts-list">`;
          for (const part of log.consumablesUsed) {
            const consumable = consumables.find(c => c.id === part.consumableId);
            const partName = consumable ? consumable.name : part.name;
            const partNum = consumable?.partNumber ? ` (${consumable.partNumber})` : '';
            html += `<span class="part-tag">${partName}${partNum} &times; ${part.quantity}</span>`;
          }
          html += `</div>`;
        }

        if (includeNotes && log.notes) {
          html += `<div class="notes-text">${log.notes}</div>`;
        }

        if (includeAttachments && log.attachments && log.attachments.length > 0) {
          html += `<p class="attachments-text"><span class="label">Attachments:</span> ${log.attachments.map(a => a.label || a.fileName).join(', ')}</p>`;
        }

        html += `</div></div>`;
      }
    }

    if (includeFuel) {
      html += `<div class="section-title">Fuel Records</div>`;
      if (eqFuelLogs.length === 0) {
        html += `<div class="no-records">No fuel records found for this date range.</div>`;
      } else {
        html += `<table><thead><tr>
          <th>Date</th>
          <th>Fuel Type</th>
          <th>Gallons</th>
          <th>DEF (gal)</th>
          <th>${metricLabel}</th>
          <th>Filled By</th>
          ${includeNotes ? '<th>Notes</th>' : ''}
        </tr></thead><tbody>`;

        let totalGallons = 0;
        let totalDef = 0;

        for (const fl of eqFuelLogs) {
          totalGallons += fl.gallons;
          totalDef += fl.defGallons || 0;
          const filledBy = fl.filledByName || (fl.filledBy.charAt(0).toUpperCase() + fl.filledBy.slice(1));

          html += `<tr>
            <td>${fl.date}</td>
            <td>${getFuelTypeLabel(fl.fuelType, fl.customFuelTypeName)}</td>
            <td>${fl.gallons.toFixed(1)}</td>
            <td>${fl.defGallons ? fl.defGallons.toFixed(1) : '\u2014'}</td>
            <td>${fl.hoursAtFillUp.toLocaleString()}</td>
            <td>${filledBy}</td>
            ${includeNotes ? `<td>${fl.notes || '\u2014'}</td>` : ''}
          </tr>`;
        }

        html += `<tr class="totals-row">
          <td colspan="2">Totals (${eqFuelLogs.length} fill-ups)</td>
          <td>${totalGallons.toFixed(1)}</td>
          <td>${totalDef > 0 ? totalDef.toFixed(1) : '\u2014'}</td>
          <td colspan="${includeNotes ? 3 : 2}"></td>
        </tr>`;

        html += `</tbody></table>`;
      }
    }

    html += `</div>`;
  }

  html += renderFooter(generationDate);
  html += `</body></html>`;
  return html;
}

export function generateFuelOnlyPdfHtml(options: FuelPdfOptions): string {
  const {
    equipment,
    fuelLogs,
    colorScheme,
    dateRange,
    generationDate,
  } = options;

  const primaryColor = getPdfPrimaryColor(colorScheme);
  const contrastText = getContrastTextColor(primaryColor);
  const logoSrc = `data:image/jpeg;base64,${LOGO_BASE64}`;

  let html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Fuel Usage Report</title>${getBaseStyles(primaryColor, contrastText)}</head><body>`;

  html += renderHeader(logoSrc, primaryColor, contrastText, 'Fuel Usage Report', generationDate, dateRange.label);

  let farmTotalGallons = 0;
  let farmTotalDef = 0;
  let farmTotalFillUps = 0;

  for (let i = 0; i < equipment.length; i++) {
    const eq = equipment[i];
    const eqFuelLogs = fuelLogs.filter(l => l.equipmentId === eq.id);
    const metricLabel = getMetricLabel(eq);

    html += `<div class="${i > 0 ? 'equipment-section' : ''}">`;
    html += renderEquipmentHeader(eq, primaryColor, contrastText);
    html += `<div class="section-title">Fuel Records</div>`;

    if (eqFuelLogs.length === 0) {
      html += `<div class="no-records">No fuel records found for this date range.</div>`;
    } else {
      html += `<table><thead><tr>
        <th>Date</th>
        <th>Fuel Type</th>
        <th>Gallons</th>
        <th>DEF (gal)</th>
        <th>${metricLabel}</th>
        <th>Filled By</th>
        <th>Notes</th>
      </tr></thead><tbody>`;

      let eqTotalGallons = 0;
      let eqTotalDef = 0;

      for (const fl of eqFuelLogs) {
        eqTotalGallons += fl.gallons;
        eqTotalDef += fl.defGallons || 0;
        const filledBy = fl.filledByName || (fl.filledBy.charAt(0).toUpperCase() + fl.filledBy.slice(1));

        html += `<tr>
          <td>${fl.date}</td>
          <td>${getFuelTypeLabel(fl.fuelType, fl.customFuelTypeName)}</td>
          <td>${fl.gallons.toFixed(1)}</td>
          <td>${fl.defGallons ? fl.defGallons.toFixed(1) : '\u2014'}</td>
          <td>${fl.hoursAtFillUp.toLocaleString()}</td>
          <td>${filledBy}</td>
          <td>${fl.notes || '\u2014'}</td>
        </tr>`;
      }

      html += `<tr class="totals-row">
        <td colspan="2">Totals (${eqFuelLogs.length} fill-ups)</td>
        <td>${eqTotalGallons.toFixed(1)}</td>
        <td>${eqTotalDef > 0 ? eqTotalDef.toFixed(1) : '\u2014'}</td>
        <td colspan="3"></td>
      </tr>`;

      html += `</tbody></table>`;

      farmTotalGallons += eqTotalGallons;
      farmTotalDef += eqTotalDef;
      farmTotalFillUps += eqFuelLogs.length;
    }

    html += `</div>`;
  }

  html += `
    <div class="farm-totals">
      <h3>Farm-Wide Totals</h3>
      <div class="totals-grid">
        <div class="total-item">
          <div class="total-value">${farmTotalGallons.toFixed(1)}</div>
          <div class="total-label">Total Gallons</div>
        </div>
        <div class="total-item">
          <div class="total-value">${farmTotalDef.toFixed(1)}</div>
          <div class="total-label">Total DEF (gal)</div>
        </div>
        <div class="total-item">
          <div class="total-value">${farmTotalFillUps}</div>
          <div class="total-label">Total Fill-Ups</div>
        </div>
      </div>
    </div>`;

  html += renderFooter(generationDate);
  html += `</body></html>`;
  return html;
}

export function sanitizeFileName(name: string): string {
  return name
    .replace(/[^a-zA-Z0-9\-_ ]/g, '')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_')
    .trim();
}

export function formatDateForFileName(date: Date): string {
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${months[date.getMonth()]}${date.getFullYear()}`;
}
